<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<bits/stdc++.h>
using namespace std;

#define FOR(a,b) for(int a=1; a<=(b); ++a)

int n, T;
int flowcap[400][400];
char lab[20][20], req[20][20];
int dirx[] = {1, 0, -1, 0};
int diry[] = {0, 1, 0, -1};
int stamp = 3;
int seen[400];
int shortest[15][15][15][15];
int reach[13][13], treach[13][13];
int infx, infy;

inline int node_id(int x, int y) { return (x-1)*n + y - 1; }

void grow(int val) {
    for (int i=1; i<=n; ++i)
        for (int j=1; j<=n; ++j)
            treach[i][j] = reach[i][j];
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=n; ++j) {
            if (treach[i][j] == val) {
                for (int d=0; d<4; ++d) {
                    int ni=i+dirx[d], nj=j+diry[d];
                    if (ni>0 && nj>0 && ni<=n && nj<=n && treach[ni][nj] < val && lab[ni][nj] != 'Y')
                        reach[ni][nj] = val;
                }
            }
        }
    }
}

bool can(int sx,int sy,int tx,int ty,int ix,int iy) {
    memset(reach,0,sizeof(reach));
    reach[sx][sy]=1;
    reach[ix][iy]=2;
    int it=100;
    while (it--) {
        grow(1);
        if (reach[tx][ty]==1) return true;
        grow(2);
        if (reach[tx][ty]==2) return false;
    }
    return false;
}

int augment(int u,int sink,int bneck) {
    if (u == sink) return bneck;
    if (seen[u] == stamp) return 0;
    seen[u] = stamp;
    for (int v=0; v<=sink; ++v) {
        if (flowcap[u][v] > 0) {
            int ret = augment(v, sink, min(bneck, flowcap[u][v]));
            if (ret) {
                flowcap[u][v] -= ret;
                flowcap[v][u] += ret;
                return ret;
            }
        }
    }
    return 0;
}

int main() {
    memset(shortest, 1, sizeof(shortest));
    cin >> n >> T;
    for (int i=1; i<=n; ++i) {
        scanf(" %s", lab[i]+1);
        for (int j=1; j<=n; ++j) {
            shortest[i][j][i][j]=0;
            if (lab[i][j]=='Z') { infx=i; infy=j; }
        }
    }
    for (int i=1; i<=n; ++i) scanf(" %s", req[i]+1);
    FOR(i,n) FOR(j,n) {
        for (int d=0; d<4; ++d) {
            int ni=i+dirx[d], nj=j+diry[d];
            if (ni>0 && ni<=n && nj>0 && nj<=n && lab[i][j]!='Y' && lab[ni][nj]!='Y')
                shortest[i][j][ni][nj]=1;
        }
    }
    FOR(kx,n) FOR(ky,n) {
        FOR(tx,n) FOR(ty,n) {
            FOR(sx,n) FOR(sy,n) {
                shortest[sx][sy][tx][ty] = min(shortest[sx][sy][tx][ty],
                                               shortest[sx][sy][kx][ky] + shortest[kx][ky][tx][ty]);
            }
        }
    }
    int src = n*n*2+1, sink=n*n*2+2;
    FOR(i,n) FOR(j,n) {
        if (isdigit(lab[i][j])) flowcap[src][node_id(i,j)] = lab[i][j]-'0';
        if (isdigit(req[i][j])) flowcap[n*n + node_id(i,j)][sink] = req[i][j]-'0';
        if (isdigit(lab[i][j])) {
            FOR(a,n) FOR(b,n) {
                if (lab[i][j] > '0' && req[a][b] > '0' && isdigit(req[a][b]) &&
                    shortest[i][j][a][b] <= T && can(i,j,a,b,infx,infy))
                    flowcap[node_id(i,j)][n*n + node_id(a,b)] = 1000;
            }
        }
    }
    int ans=0, ret;
    while ((ret = augment(src,sink,1000))) {
        ans += ret;
        ++stamp;
    }
    cout << ans << '\n';
    return 0;
}
